import{_ as a,C as i,o,c as r,ag as c,E as n}from"./chunks/framework.cyF4XceO.js";const v=JSON.parse('{"title":"仕様","description":"","frontmatter":{},"headers":[],"relativePath":"ja/spec/index.md","filePath":"ja/spec/index.md"}'),d={name:"ja/spec/index.md"};function s(l,e,p,m,h,f){const t=i("StatusNote");return o(),r("div",null,[e[0]||(e[0]=c('<h1 id="仕様" tabindex="-1">仕様 <a class="header-anchor" href="#仕様" aria-label="Permalink to &quot;仕様&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>exact な <strong>FormRef</strong> は、API group・kind・definition version・schema digest の 組み合わせです。互換性は kind 名だけから推測しません — epoch が違えば別の契約です。 Form group は <a href="/spec/form-families.html">Form Families</a> で namespace 化され、 Host API group はどの Form group からも独立した protocol 互換性 identity です。</p><table tabindex="0"><thead><tr><th>Surface</th><th>Identity</th></tr></thead><tbody><tr><td>API/Core checkpoint</td><td><code>v1.0.1</code>。外部 Core の public compatibility checkpoint。<code>forms.takoform.com/v1</code> lane を使い、Host の実装・support・deployment とは別の事実</td></tr><tr><td>Historical Specification receipt</td><td>Takoform 1.1。first numbered release の sealed exact source receipt。publication state は append-only numbered ledger から導出し、1.0 は公開前に撤回され再利用しない</td></tr><tr><td>Provider 3 retained mapping</td><td>8 versionless families / 31 exact Experimental <code>0.x</code> typed mappings。active standalone Edge publisher の roster や package publication ではない</td></tr><tr><td>Host API candidate</td><td><code>forms.takoform.com/v1</code> (discovery は <code>/.well-known/takoform/v1</code>、Specification とは separate and unpublished)</td></tr><tr><td>現在の package envelope</td><td><code>packages.forms.takoform.com/v1alpha5</code> (unpublished)</td></tr><tr><td>Provider distribution</td><td>independent。Provider 3.0.0 は current Registry-published non-normative reference implementation、<code>v2.1.1</code> は retained history</td></tr></tbody></table><p>Specification 1.1 は separate Host API v1 candidate を publish / promote せず、 current Form を <code>1.0.0</code> に昇格させず、Package や Provider を publish せず、 <code>/v1.1</code> / v2 lane も mint しません。</p><p>W09 は C1（normative freeze）、C2（source evidence のみ）、C3（authoritative receipt のみ）、その direct child である C4（bounded deterministic public refresh）を squash しない linear boundary として保持します。C4 は normative source、evidence、ledger、release tooling、Provider/Form/Host source、unrelated file を変更できません。</p><p>pre-Beta の epoch（<code>forms.takoform.com/v1alpha1</code> と <code>/v1alpha2</code>）は撤回されました (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>)。 identity は公開台帳に retired として記録され、バイト列はリポジトリ履歴に残ります。 provider の SemVer はどの API identity からも独立しています。</p><h2 id="現在レーンの契約-英語のみ" tabindex="-1">現在レーンの契約 (英語のみ) <a class="header-anchor" href="#現在レーンの契約-英語のみ" aria-label="Permalink to &quot;現在レーンの契約 (英語のみ)&quot;">​</a></h2><ul><li><a href="/spec/form-families.html">Form Families</a> — namespace 化された Form group と Edge Platform Family</li><li><a href="/spec/host-api/v1.html">Host API v1</a> — uid/generation/revision 識別・long-running operation・fencing</li><li><a href="/spec/interface-contract/">Interface contracts</a> — Form のサービスが公開する exact な capability 契約</li><li><a href="/spec/binding-contract/">Binding contracts</a> — revision が保持する typed な capability 利用</li><li><a href="/spec/artifact-transport/">Artifact transport</a> — content-addressed な artifact upload と manifest</li></ul><h2 id="normative-schemas" tabindex="-1">Normative schemas <a class="header-anchor" href="#normative-schemas" aria-label="Permalink to &quot;Normative schemas&quot;">​</a></h2><p>stable Host/API schema identity は append-only local contract lock に記録します:</p><ul><li><a href="/schemas/v1/form-ref.schema.json">form-ref v1</a></li><li><a href="/schemas/v1/form-definition.schema.json">form-definition v1</a></li><li><a href="/schemas/v1/host-api-wire.schema.json">host-api-wire v1</a></li><li><a href="/schemas/v1alpha5/package-index.schema.json">package-index v1alpha5</a></li></ul><p>撤回された epoch の schema identity は <a href="/release/public-schema-identities.json"><code>release/public-schema-identities.json</code></a> に retired として記録され、再利用されません。</p><h2 id="ライフサイクル" tabindex="-1">ライフサイクル <a class="header-anchor" href="#ライフサイクル" aria-label="Permalink to &quot;ライフサイクル&quot;">​</a></h2><p>Form は Proposal → Experimental → Stable → Legacy の順に、Specification とは 独立して進みます。future stable Form は explicit per-Form decision により <code>1.0.0</code> から始まります。</p>',15)),n(t)])}const b=a(d,[["render",s]]);export{v as __pageData,b as default};
